"""Source catalogue. Evidence tags: [OBS]=observed in this study (probe/pit_probes/collect logs), [DOC]=stated on a provider page fetched
in this study (results/license_evidence.json) or provider API response, [INF]=inference, [UNK]=unknown/not verified.
exec: Y = >=1 successful, parsed data pull logged under results/ or data/collect_log.json ; N = not executed (blocked/keyed/timeout/reachable-only)
pit: PIT_NATIVE | PIT_ADAPTABLE | LOOKAHEAD_RISK | SNAPSHOT_ONLY  (see 06_PIT_READINESS.md for exact definitions)
info: TESTED_CANDIDATE | TESTED_NO_INCREMENT | TESTED_PRICE_DERIVATIVE | UNTESTED_NEEDS_FORWARD_CAPTURE | UNTESTED_BLOCKED | PRICE_DATA_NOT_ALT | UNTESTED_LOW_POWER
"""
def S(id, name, cat, exec, cost, access, pit, info, licence, ts, rev, rate, coverage, probes=(), history="", note="", tested="N", pitnote=""):
    return dict(id=id, name=name, cat=cat, exec=exec, cost=cost, access=access, pit=pit, info=info, licence=licence, ts=ts, rev=rev, rate=rate,
                coverage=coverage, probes=list(probes), history=history, note=note, tested=tested, pitnote=pitnote)

